<?php
require __DIR__.'/_common.php'; admin_require(); $pdo=db();$rows=$pdo->query('SELECT id,order_number,amount,currency,payment_provider,payment_status,maketou_reference,payment_url,created_at,updated_at FROM orders ORDER BY id DESC LIMIT 300')->fetchAll();$events=[];try{$events=$pdo->query('SELECT id,provider,event_id,order_id,status,created_at FROM payment_events ORDER BY id DESC LIMIT 100')->fetchAll();}catch(Throwable $e){}admin_layout_start('Paiements');echo '<h2>Transactions</h2><table><tr><th>Commande</th><th>Montant</th><th>Provider</th><th>Statut</th><th>Référence</th><th>Checkout</th><th>Date</th></tr>';foreach($rows as $r)echo '<tr><td>'.h($r['order_number']).'</td><td>'.h($r['amount'].' '.$r['currency']).'</td><td>'.h($r['payment_provider']??'').'</td><td>'.h($r['payment_status']).'</td><td>'.h($r['maketou_reference']??'').'</td><td>'.($r['payment_url']?'<a target="_blank" href="'.h($r['payment_url']).'">Ouvrir</a>':'').'</td><td>'.h($r['created_at']).'</td></tr>';echo '</table><h2>Événements webhook</h2><table><tr><th>ID</th><th>Provider</th><th>Event</th><th>Commande</th><th>Statut</th><th>Date</th></tr>';foreach($events as $e)echo '<tr><td>'.h($e['id']).'</td><td>'.h($e['provider']).'</td><td>'.h($e['event_id']).'</td><td>'.h($e['order_id']).'</td><td>'.h($e['status']).'</td><td>'.h($e['created_at']).'</td></tr>';echo '</table>';admin_layout_end();